insert into public.inspirations
  (slug, title, creator, category, source, tags, description, original_url, image_url, image_alt, published_at, published)
values
  ('the-great-wave', 'The Great Wave', 'Katsushika Hokusai', 'Print', 'The Met', array['japanese prints', 'water', 'landscape'], 'Hokusai frames Mount Fuji through the curved silhouette of a breaking wave.', 'https://www.metmuseum.org/art/collection/search/45434', '/previews/the-great-wave.webp', 'A curling, blue-and-white wave towers over boats with Mount Fuji in the distance.', '2026-11-18T00:00:00.000Z', true),
  ('the-grand-tour', 'The Grand Tour', 'NASA / JPL-Caltech', 'Posters', 'NASA JPL', array['space', 'travel', 'graphic design'], 'A retro travel poster turns the Voyager mission’s outer-planet itinerary into a bold piece of typography and illustration.', 'https://www.jpl.nasa.gov/images/the-grand-tour-jpl-travel-poster/', '/previews/the-grand-tour.webp', 'An illustrated outer-planet travel poster with orbit trails and bold display lettering.', '2026-11-17T00:00:00.000Z', true),
  ('earth-from-expedition-44', 'Earth from Expedition 44', 'NASA', 'Photography', 'NASA', array['space', 'earth'], 'A view of Earth photographed by a crew member aboard the International Space Station.', 'https://images.nasa.gov/details/iss044e002419', '/previews/earth-from-expedition-44.webp', 'An orbital photograph of Earth taken aboard the International Space Station.', '2026-11-16T00:00:00.000Z', true),
  ('europa', 'Europa', 'NASA / JPL-Caltech', 'Posters', 'NASA JPL', array['space', 'travel', 'graphic design'], 'A speculative travel poster for Jupiter’s icy moon, from JPL’s Visions of the Future series.', 'https://www.jpl.nasa.gov/images/europa-jpl-travel-poster/', '/previews/europa.webp', 'Illustrated Europa travel poster with bold lettering and a limited palette.', '2026-11-15T00:00:00.000Z', true),
  ('wheat-field-with-cypresses', 'Wheat Field with Cypresses', 'Vincent van Gogh', 'Painting', 'The Met', array['landscape', 'texture'], 'Van Gogh sets the deep vertical forms of cypresses against a field of wheat and rolling clouds.', 'https://www.metmuseum.org/art/collection/search/436535', '/previews/wheat-field-with-cypresses.webp', 'A golden field below white clouds and dark cypress trees.', '2026-11-14T00:00:00.000Z', true),
  ('duck-and-scallions', 'Duck and Scallions', 'Ryūryūkyo Shinsai', 'Print', 'The Met', array['japanese prints', 'food'], 'An intimate Japanese print from the Spring Rain Collection.', 'https://www.metmuseum.org/art/collection/search/54811', '/previews/duck-and-scallions.webp', 'A duck and scallions illustrated on a pale ground.', '2026-11-13T00:00:00.000Z', true),
  ('aqua-satellite', 'Aqua Satellite', 'NASA', 'Illustration', 'NASA', array['space', 'earth'], 'An artist’s concept of the Aqua satellite in orbit around Earth.', 'https://images.nasa.gov/details/PIA18156', '/previews/aqua-satellite.webp', 'An illustration of a satellite with a wide solar panel above the blue Earth.', '2026-11-12T00:00:00.000Z', true),
  ('titan', 'Titan', 'NASA / JPL-Caltech', 'Posters', 'NASA JPL', array['space', 'travel', 'graphic design'], 'JPL imagines a cruise on Titan’s methane seas in the visual language of a vintage travel poster.', 'https://www.jpl.nasa.gov/images/titan-jpl-travel-poster/', '/previews/titan.webp', 'An illustrated travel poster for a cruise on Saturn’s moon Titan.', '2026-11-11T00:00:00.000Z', true),
  ('oiso', 'Ōiso', 'Utagawa Hiroshige', 'Print', 'The Met', array['japanese prints', 'landscape', 'travel'], 'A woodblock print by Hiroshige from his studies of landscapes along the Tōkaidō.', 'https://www.metmuseum.org/art/collection/search/36553', '/previews/oiso.webp', 'A woodblock landscape depicting Ōiso.', '2026-11-10T00:00:00.000Z', true),
  ('shoes', 'Shoes', 'Vincent van Gogh', 'Painting', 'The Met', array['texture', 'still life'], 'Loaded brushwork and a muted palette turn a pair of shoes into a study in texture.', 'https://www.metmuseum.org/art/collection/search/436533', '/previews/shoes.webp', 'Worn shoes painted against a textured ground.', '2026-11-09T00:00:00.000Z', true),
  ('head-of-the-virgin', 'Head of the Virgin', 'Leonardo da Vinci', 'Drawing', 'The Met', array['portrait', 'texture'], 'Leonardo uses soft transitions in tone to model the face in this study.', 'https://www.metmuseum.org/art/collection/search/337496', '/previews/head-of-the-virgin.webp', 'A softly shaded drawing of a head facing right.', '2026-11-08T00:00:00.000Z', true),
  ('earth-from-expedition-46', 'Earth from Expedition 46', 'NASA', 'Photography', 'NASA', array['space', 'earth'], 'An Earth observation image from the International Space Station.', 'https://images.nasa.gov/details/iss046e009103', '/previews/earth-from-expedition-46.webp', 'An orbital photograph of Earth captured during Expedition 46.', '2026-11-07T00:00:00.000Z', true)
